SET LOCAL search_path = "chat", pg_catalog;
CREATE TABLE interaction_preferences(wallet text PRIMARY KEY,inbox text NOT NULL CHECK(inbox IN ('everyone','followed_only','nobody')),revision bigint NOT NULL DEFAULT 1 CHECK(revision>0));
CREATE TABLE interaction_blocks(owner text NOT NULL,target text NOT NULL,PRIMARY KEY(owner,target),CHECK(owner<>target));
CREATE TABLE interaction_mutes(owner text NOT NULL,target text NOT NULL,PRIMARY KEY(owner,target));
CREATE TABLE interaction_erased_wallets(wallet text PRIMARY KEY,deletion_case_id uuid NOT NULL,policy_version text NOT NULL,erased_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE interaction_erasure_jobs(deletion_case_id uuid PRIMARY KEY,wallet text NOT NULL,policy_version text NOT NULL,stage integer NOT NULL DEFAULT 0,state text NOT NULL DEFAULT 'running',rows_processed bigint NOT NULL DEFAULT 0,completed_at timestamptz,hold_until timestamptz);
CREATE TABLE interaction_erasure_receipts(deletion_case_id uuid PRIMARY KEY,wallet text NOT NULL,policy_version text NOT NULL,completed_at timestamptz NOT NULL,receipt_hash text NOT NULL);
CREATE TABLE interaction_public_events(event_id text PRIMARY KEY,aggregate_id text NOT NULL,revision bigint NOT NULL,payload bytea NOT NULL,payload_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL DEFAULT now()+interval '72 hours',UNIQUE(aggregate_id,revision));
CREATE TABLE interaction_feed_projection(generation text NOT NULL,aggregate_id text NOT NULL,revision bigint NOT NULL,actor text NOT NULL,removed boolean NOT NULL,payload bytea NOT NULL,PRIMARY KEY(generation,aggregate_id));
CREATE INDEX ON interaction_feed_projection(actor,generation);
CREATE TABLE interaction_callout_authority(id text NOT NULL,revision bigint NOT NULL,actor text NOT NULL,removed boolean NOT NULL,PRIMARY KEY(id,revision));
CREATE TABLE interaction_visibility_revision(scope text PRIMARY KEY,revision bigint NOT NULL CHECK(revision>0));
CREATE INDEX ON interaction_public_events(expires_at,event_id);
REVOKE ALL ON "chat"."interaction_preferences" FROM PUBLIC;
REVOKE ALL ON "chat"."interaction_blocks" FROM PUBLIC;
REVOKE ALL ON "chat"."interaction_mutes" FROM PUBLIC;
REVOKE ALL ON "chat"."interaction_erased_wallets" FROM PUBLIC;
REVOKE ALL ON "chat"."interaction_erasure_jobs" FROM PUBLIC;
REVOKE ALL ON "chat"."interaction_erasure_receipts" FROM PUBLIC;
REVOKE ALL ON "chat"."interaction_public_events" FROM PUBLIC;
REVOKE ALL ON "chat"."interaction_feed_projection" FROM PUBLIC;
REVOKE ALL ON "chat"."interaction_callout_authority" FROM PUBLIC;
REVOKE ALL ON "chat"."interaction_visibility_revision" FROM PUBLIC;
CREATE VIEW chat.safety_visibility_v2 AS SELECT target_type,target_id,status,revision FROM chat.safety_visibility;
REVOKE ALL ON chat.safety_visibility_v2 FROM PUBLIC;
